"""Standalone explorer for role/component fixed-decoder aggregation comparisons."""
import json
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'texture_aggregation_20261102'
cfg=json.loads((D/'PROTOCOL.json').read_text());a=pd.read_csv(D/'IMAGE_ALIGNMENT.csv')
groups=[]
for i,(component,g) in enumerate(a.groupby('component',sort=True)):
    groups.append(dict(id=i,component=component,role=g.role.iloc[0],proxy=int(g.proxy_class.iloc[0]),images=len(g)))
group_id={r['component']:r['id'] for r in groups};layers=['encoded','masked_context'];variants=cfg['variants']
tiles=pd.read_csv(D/'TILE_UTILITY_SUMMARY.csv');packed=[]
for r in tiles.itertuples():packed.append([layers.index(r.layer),group_id[r.component],int(r.view),variants.index(r.variant),int(r.tile),int(r.available),float(r.loss_sum)])
data=dict(groups=groups,layers=layers,variants=variants,
    summary=json.loads(pd.read_csv(D/'UTILITY_SUMMARY.csv').to_json(orient='records',double_precision=15)),
    components=json.loads(pd.read_csv(D/'COMPONENT_UTILITY.csv').to_json(orient='records',double_precision=15)),tiles=packed)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRACE aggregation investigation</title>
<style>*{box-sizing:border-box}:root{color-scheme:light;--ink:#183c49;--teal:#218a81}body{font:16px/1.55 system-ui;background:#f2f6f6;color:var(--ink);margin:0}main{max-width:1200px;margin:auto;padding:25px 20px 55px}header{background:#183c49;color:white;padding:28px;border-radius:16px}h1{font-size:clamp(27px,4vw,42px);margin:4px 0 12px;line-height:1.15}h2{font-size:25px;margin:0 0 12px}.eyebrow{font-size:12px;letter-spacing:.13em;color:#b6ddd6}a{color:#12685f}header a{color:#b6e4d9}p{max-width:90ch}.note{color:#5b7077;font-size:14px}section{background:white;border:1px solid #dbe5e3;padding:22px;border-radius:14px;margin-top:20px}select{font:inherit;background:white;border:1px solid #b7cac6;padding:8px;border-radius:8px;max-width:100%;color:var(--ink)}label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:18px 0}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin:18px 0}.stat{background:#edf5f2;padding:14px;border-radius:9px}.stat b{display:block;font-size:27px}.stat small{font-size:12px}.columns{display:grid;grid-template-columns:1.1fr 1fr;gap:24px}.barrow{display:grid;grid-template-columns:minmax(145px,1fr) 1.2fr 65px;gap:9px;font-size:13px;align-items:center;margin:9px 0}.track{background:#edf2f1;border-radius:4px;height:15px}.fill{height:100%;background:var(--teal);border-radius:4px}canvas{width:100%;max-width:440px;height:auto;background:#edf2f2}img{width:100%;height:auto}.legend{font-size:13px}.warm{color:#b04a32}.cool{color:#316aa5}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #dae5e2;padding:10px}@media(max-width:760px){.columns{grid-template-columns:1fr}section,header{padding:17px}.barrow{grid-template-columns:1.1fr 1fr 62px}}</style>
<main><header><div class="eyebrow">SAVED FEATURES · FINAL EPOCH60 · NO RETRAINING</div><h1>Where does local texture detail survive?</h1><p>Compare nine fixed aggregation interventions through the unchanged TRACE decoder. Local reconstruction bypasses the global vector; useful local detail and low pooled diversity can coexist.</p><p><a href="../phase3TextureAggregationInvestigation.md">Full investigation</a> · <a href="METHODS.md">Exact methods and data dictionary</a></p></header>
<section><h2>Explore the fixed-decoder evidence</h2><p>Values are reconstruction losses and retained advantage over the train-position control.100% retention equals original utility;0% equals the control. Negative values are worse than that control. These are not accuracy percentages.</p>
<div class="filters"><label>Decoder branch<select id="layer"><option value="encoded">Local unpooled texture</option><option value="masked_context">Masked spatial context</option></select></label><label>Original role<select id="role"><option value="train">Train</option><option value="validation">Validation</option><option value="test">Historical test</option></select></label><label>Component<select id="component"></select></label><label>Recorded view<select id="view"><option value="0">View0: clean, primary</option><option value="1">View1: saved perturbation</option></select></label><label>Aggregation<select id="variant"></select></label></div>
<p id="scope" class="note"></p><div class="stats"><div class="stat"><b id="retained"></b><small>Original control advantage retained</small></div><div class="stat"><b id="original"></b><small>Original decoder loss</small></div><div class="stat"><b id="altered"></b><small>Aggregated decoder loss</small></div><div class="stat"><b id="control"></b><small>Train-position control loss</small></div></div>
<div class="columns"><div><h2>All nine comparisons</h2><div id="bars"></div><p class="note">Training templates/scales use only the386 training images. No new head was trained to adapt to the transformed features, so these are fixed-head interventions.</p></div><div><h2>Extra loss by canonical tile</h2><canvas id="tiles" width="440" height="520" aria-label="Eight by four map of extra descriptor reconstruction loss"></canvas><p class="legend"><span class="warm">Warm: higher loss</span> · <span class="cool">Cool: lower loss</span> · white: unavailable. Scale ±0.25 Huber, clipped for colour; labels show the actual difference.</p><p class="note">Tile losses are means over available images. Components combine using recorded numerator/availability counts. This is a canonical descriptor-loss map, not a physical damage or depth image.</p></div></div></section>
<section><h2>What the primary evidence says</h2><ul><li>One average retains about61% of local validation utility. A fixed position template plus five residual moments retains about82%.</li><li>Averaging disproportionately damages orientation and contrast detail. A fixed train template alone retains only about8% of the local advantage.</li><li>Full-context feature diversity narrows before pooling. Effective rank can also increase through invertible scaling, without new information.</li><li>High masked-context rank strongly tracks mask placement. The original projector uses unmasked full-context features.</li></ul><p>The original global selection gates remain unchanged: selected=None. No mileage-classification, physical-depth or safety improvement is claimed.</p></section>
<section><h2>Scientific figures</h2><img src="figures/Aggregation_Utility.png" alt="Controlled reconstruction utility, group differences and descriptor errors"><img src="figures/Aggregation_Mechanism.png" alt="Feature diversity, spatial covariance, mask-plan alignment and invertible scaling"></section>
<section><h2>Scope and saved evidence</h2><p>570existing images, two retained views, no new image/geometry encoder forwards or optimizer updates.656,640decoder-token readouts and1,140projector-vector readouts are explicitly counted. The cohorts were already inspected. New derivatives are local and not HF-published.</p><p><a href="UTILITY_SUMMARY.csv">Role utility CSV</a> · <a href="COMPONENT_UTILITY.csv">Component CSV</a> · <a href="CHANNEL_UTILITY_SUMMARY.csv">Descriptor CSV</a> · <a href="PROTOCOL.json">Frozen protocol</a> · <a href="NATIVE_INPUTS.csv">Exact input hashes</a></p></section></main>
<script type="application/json" id="data">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),el=id=>document.getElementById(id);
const names={identity:'Original unpooled',global_mean:'One average',band_means:'8 band means',column_means:'4 column means',moments5:'5 spatial moments',random5:'5 fixed random modes',train_template:'Fixed train template',residual_mean:'Template + mean residual',residual_moments5:'Template + 5 residual moments'};
function state(){return {layer:el('layer').value,role:el('role').value,view:Number(el('view').value),component:el('component').value,variant:el('variant').value};}
function summary(s,variant=s.variant){if(s.component==='all')return data.summary.find(r=>r.layer===s.layer&&r.role===s.role&&r.view===s.view&&r.variant===variant);const group=data.groups[Number(s.component)];return data.components.find(r=>r.layer===s.layer&&r.component===group.component&&r.view===s.view&&r.variant===variant);}
function tileMeans(s,variant=s.variant){const sums=Array(32).fill(0),counts=Array(32).fill(0),layer=data.layers.indexOf(s.layer),v=data.variants.indexOf(variant);for(const r of data.tiles){const g=data.groups[r[1]];if(r[0]===layer&&r[2]===s.view&&r[3]===v&&g.role===s.role&&(s.component==='all'||r[1]===Number(s.component))){counts[r[4]]+=r[5];sums[r[4]]+=r[6];}}return sums.map((sum,i)=>counts[i]?sum/counts[i]:null);}
function node(tag,text){const n=document.createElement(tag);n.textContent=text;return n;}
function components(){el('component').replaceChildren();const first=node('option','All components in role');first.value='all';el('component').append(first);for(const g of data.groups.filter(g=>g.role===el('role').value)){const option=node('option',['low','mid','high'][g.proxy]+' proxy · '+g.component.replace('tyre:','')+' · '+g.images+' images');option.value=String(g.id);el('component').append(option);}el('component').value='all';}
function render(){const s=state(),r=summary(s);el('retained').textContent=(r.retained_gain_fraction*100).toFixed(2)+'%';el('original').textContent=r.native_original_loss.toFixed(6);el('altered').textContent=r.loss.toFixed(6);el('control').textContent=r.position_control_loss.toFixed(6);el('scope').textContent=r.images+' correlated image records / '+s.role+' / recorded view'+s.view+' / final epoch60. No checkpoint reselection.';
el('bars').replaceChildren();for(const variant of data.variants){const row=summary(s,variant),block=node('div','');block.className='barrow';const track=node('div',''),fill=node('div','');track.className='track';fill.className='fill';fill.style.width=Math.min(100,Math.abs(row.retained_gain_fraction)*100)+'%';if(row.retained_gain_fraction<0)fill.style.background='#bf6e4b';track.append(fill);block.append(node('span',names[variant]),track,node('b',(row.retained_gain_fraction*100).toFixed(1)+'%'));el('bars').append(block);}
const value=tileMeans(s),base=tileMeans(s,'identity'),canvas=el('tiles'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,440,520);ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillStyle='#183c49';for(let c=0;c<4;c++)ctx.fillText('Column '+(c+1),70+c*100,20);for(let t=0;t<32;t++){const x=22+(t%4)*100,y=34+Math.floor(t/4)*59;const delta=value[t]===null||base[t]===null?null:value[t]-base[t];if(delta===null)ctx.fillStyle='#fff';else{const q=Math.min(1,Math.abs(delta)/.25);ctx.fillStyle=delta>=0?'rgb(245,'+Math.round(241-140*q)+','+Math.round(235-165*q)+')':'rgb('+Math.round(235-150*q)+','+Math.round(244-80*q)+',248)';}ctx.fillRect(x,y,94,52);ctx.fillStyle='#183c49';ctx.fillText(delta===null?'Unavailable':(delta>=0?'+':'')+delta.toFixed(3),x+47,y+29);}}
for(const v of data.variants){const option=node('option',names[v]);option.value=v;el('variant').append(option);}el('layer').value='encoded';el('role').value='validation';el('view').value='0';el('variant').value='global_mean';components();
el('role').addEventListener('change',()=>{components();render();});for(const key of ['layer','component','view','variant'])el(key).addEventListener('change',render);
globalThis.aggregationAudit={data,summary,tileMeans,state,render,names};render();
</script></html>'''
payload=json.dumps(data,separators=(',',':'),ensure_ascii=True,allow_nan=False).replace('<','\\u003c')
(D/'Aggregation_Explorer.html').write_text(html.replace('__DATA__',payload),encoding='utf-8',newline='\n')
print('Aggregation explorer:',(D/'Aggregation_Explorer.html').stat().st_size,'bytes; all role/component views and nine interventions.')
